def rearange_string(s):
  char_count = Counter(s)
  max_count = max(char_count.values())
  if max_count > len(s)//2:
    return "Not possible"
  else:
    odd_chars = [char for char, count in char_count.items() if count % 2 != 0]
    even_chars = [char for char, count in char_count.items() if count % 2 == 0]
    result = []
    while odd_chars:
      result.append(odd_chars.pop(0))
      if even_chars:
        result.append(even_chars.pop(0))
    return ''.join(result)

