def no_of_subsequences(arr,k):
  count = 0
  for i in range(len(arr)):
    for j in range(i+1,len(arr)+1):
      product = 1
      for num in combinations(arr[i:j],1):
        product *= num
      if product < k:
        count += 1
  return count
